import app from 'flarum/forum/app';
import Avatar from 'flarum/common/components/Avatar';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import formatNumber from 'flarum/common/utils/formatNumber';
import BadgesBasePage from './BadgesBasePage';
import { badgesEnabled } from '../utils';
import { fullDate, shortAge } from '../../../utils/dates';
import { t } from '../../../utils/settings';
const PAGE_SIZE = 30;

/**
 * A página de um emblema (/badges/:id/:slug): a medalha grande, o texto longo
 * e quem ganhou, dos mais recentes aos mais antigos. Com `?username=`, vinda
 * do perfil ou de uma notificação, a pessoa aparece em destaque na lista.
 */
export default class BadgePage extends BadgesBasePage {
  badge = null;
  grants = [];
  loading = true;
  hasMore = false;
  failed = false;
  oninit(vnode) {
    super.oninit(vnode);
    if (!badgesEnabled()) return;
    const id = m.route.param('id');

    // O Show traz a descrição longa, que a listagem da página /badges não traz.
    app.store.find('canela-badges', id).then(badge => {
      this.badge = badge;
      this.updateTitle();
      app.history.push(this.attrs.routeName, this.title());
    }).catch(() => this.failed = true).finally(() => m.redraw());
    this.loadGrants(id, 0);
  }
  loadGrants(badgeId, offset) {
    this.loading = true;
    app.store.find('canela-user-badges', {
      filter: {
        badge: badgeId
      },
      include: 'badge,user,post,post.discussion',
      page: {
        offset,
        limit: PAGE_SIZE
      }
    }).then(result => {
      this.grants.push(...result);
      this.hasMore = !!result.payload?.links?.next;
    }).catch(() => this.hasMore = false).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  title() {
    return this.badge?.name() || t('badges.page_title');
  }
  className() {
    return 'CanelaBadgeShow';
  }
  content() {
    if (this.failed) return m("p", {
      className: "CanelaBadges-empty"
    }, t('badges.not_found'));
    if (!this.badge) return m(LoadingIndicator, {
      display: "block"
    });
    const badge = this.badge;
    const count = badge.grantCount() || 0;
    const type = badge.type() || 'bronze';

    // O `show-badge` do Discourse: "Emblemas / Nome" como título, o cartão
    // grande com o texto longo e, embaixo, quem ganhou em grade.
    return m("div", {
      className: "CanelaBadgeShow-inner"
    }, m("h1", {
      className: "CanelaBadges-title CanelaBadgeShow-title"
    }, m(Link, {
      href: app.route('canela.badges')
    }, t('badges.page_title')), " / ", badge.name()), m("div", {
      className: "CanelaBadgeShow-details"
    }, m("div", {
      className: classList('CanelaBadgeCard', 'CanelaBadgeCard--large', `CanelaBadgeCard--${type}`)
    }, m("span", {
      className: "CanelaBadgeCard-contents"
    }, m("span", {
      className: `CanelaBadgeCard-icon CanelaBadgeCard-icon--${type}`,
      title: t(`badges.types.${type}`),
      "aria-hidden": "true"
    }, m(Icon, {
      name: badge.icon() || 'fas fa-certificate'
    })), m("span", {
      className: "CanelaBadgeCard-info"
    }, m("h3", {
      className: "CanelaBadgeCard-name"
    }, badge.name()), m("span", {
      className: "CanelaBadgeCard-description CanelaBadgeShow-long"
    }, badge.longDescription() || badge.description()), m("span", {
      className: "CanelaBadgeCard-meta"
    }, t('badges.awarded', {
      count,
      number: formatNumber(count)
    }), badge.multipleGrant() && m("span", null, " \xB7 ", t('badges.multiple_grant'))))))), this.grantList());
  }
  grantList() {
    if (!this.grants.length) {
      return this.loading ? m(LoadingIndicator, {
        display: "block"
      }) : m("p", {
        className: "CanelaBadges-empty"
      }, t('badges.no_recipients'));
    }
    const highlighted = (m.route.param('username') || '').toLowerCase();
    return m("div", {
      className: "CanelaBadgeShow-recipients"
    }, m("ul", {
      className: "CanelaBadgeRecipients"
    }, this.grants.map(grant => this.grantItem(grant, highlighted))), this.hasMore && m("div", {
      className: "CanelaBadgeShow-more"
    }, m(Button, {
      className: "Button",
      loading: this.loading,
      onclick: () => this.loadGrants(this.badge.id(), this.grants.length)
    }, t('badges.load_more'))));
  }

  /** O motivo de uma concessão manual: link (só http/https) ou texto. */
  reason(grant) {
    const reason = grant.reason();
    if (!reason) return null;
    if (/^https?:\/\//i.test(reason)) {
      return m("a", {
        className: "CanelaBadgeRecipient-post CanelaBadgeRecipient-reason",
        href: reason,
        rel: "nofollow ugc noopener",
        target: "_blank"
      }, reason);
    }
    return m("span", {
      className: "CanelaBadgeRecipient-post CanelaBadgeRecipient-reason"
    }, reason);
  }
  grantItem(grant, highlighted) {
    const user = grant.user();
    const post = grant.post();
    const discussion = post ? post.discussion() : false;
    const grantedAt = grant.grantedAt();
    if (!user) return null;
    return m("li", {
      key: grant.id(),
      className: classList('CanelaBadgeRecipient', {
        'CanelaBadgeRecipient--highlight': highlighted && user.username().toLowerCase() === highlighted
      })
    }, m(Link, {
      className: "CanelaBadgeRecipient-avatar",
      href: app.route.user(user),
      tabindex: "-1",
      "aria-hidden": "true"
    }, m(Avatar, {
      user: user
    })), m("div", {
      className: "CanelaBadgeRecipient-detail"
    }, m(Link, {
      className: "CanelaBadgeRecipient-user",
      href: app.route.user(user)
    }, m("span", {
      className: "CanelaBadgeRecipient-username"
    }, user.displayName() !== user.username() ? `@${user.username()}` : user.username()), user.displayName() !== user.username() && m("span", {
      className: "CanelaBadgeRecipient-name"
    }, user.displayName())), grantedAt && m("div", {
      className: "CanelaBadgeRecipient-date"
    }, app.translator.trans('ramon-canela.forum.badges.granted_ago', {
      ago: m("time", {
        datetime: grantedAt.toISOString(),
        title: fullDate(grantedAt)
      }, shortAge(grantedAt))
    })), post && discussion && m(Link, {
      className: "CanelaBadgeRecipient-post",
      href: app.route.post(post)
    }, discussion.title()), this.reason(grant)));
  }
}
flarum.reg.add('ramon-canela', 'forum/features/badges/components/BadgePage', BadgePage);